namespace COT_VCF.Application.Results;

/// <summary>Browser-side report controls, following the same embedded-data/inline-script pattern as MB reports.</summary>
internal static class FemLiveReportAssets
{
    public const string Style = """
:root{--acc:#1f4788;--bd:#c7ccd2;--su:#f3f4f6;--tx:#1a1a1a;--mu:#666}
*{box-sizing:border-box}body{margin:0;font:13px/1.4 Segoe UI,Arial,sans-serif;color:var(--tx);background:#fff}
[hidden]{display:none!important}header{padding:10px 14px;border-bottom:2px solid var(--acc)}h1{font-size:16px;margin:0;color:var(--acc)}
header>div,header p{margin:3px 0;color:var(--mu);font-size:11.5px}nav{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:6px 14px;border-bottom:1px solid var(--bd);background:#fff}
select,button{font:12px Segoe UI,Arial;padding:4px 7px;border:1px solid var(--bd);border-radius:3px;background:#fff}button{cursor:pointer}button:hover{background:var(--su)}label{white-space:nowrap}.hint{color:var(--mu);font-size:11px}
#scope{padding:6px 14px;color:var(--mu);font-size:11px}.panel{margin:0 14px 12px;padding:8px 10px;border:1px solid var(--bd);break-inside:avoid}.panel h2{margin:0 0 4px;color:var(--acc);font-size:13px}.panel p{margin:2px 0 8px;color:var(--mu);font-size:11px}
.stage{display:grid;grid-template-columns:minmax(0,1fr) 190px;gap:12px}.chart{display:block;width:100%;height:auto;min-height:280px}.legend{border-left:1px solid var(--bd);padding:8px;font-size:11px;line-height:1.6}.key{display:block;white-space:normal}.swatch{display:inline-block;width:12px;height:3px;margin-right:5px;vertical-align:middle}
#source{margin:12px 14px}#source h2{font-size:13px;color:var(--acc)}#source table{border-collapse:collapse;width:100%;font:11px Consolas,monospace}#source th,#source td{padding:4px 6px;border:1px solid var(--bd);text-align:right}#source th:first-child,#source td:first-child{text-align:left}#source th{background:var(--su)}
#tip{position:fixed;pointer-events:none;z-index:50;max-width:320px;padding:6px 8px;border-radius:3px;background:#212121;color:#fff;font:11px/1.45 Consolas,monospace;white-space:pre-line;box-shadow:0 8px 16px #0003}
.empty{padding:24px;color:var(--mu)}.warning{color:#a44b00}.pr-sheet nav{position:static}.pr-sheet .panel{margin:0;padding:0;border:0}.pr-sheet .stage{grid-template-columns:minmax(0,1fr) 150px}.pr-sheet .chart{min-height:0}.pr-sheet .legend{font-size:9px}
""";

    public const string Script = """
(()=>{
const D=JSON.parse(document.getElementById('fem-data').textContent),CASE=document.getElementById('case'),TOPIC=document.getElementById('topic'),FRAME=document.getElementById('frame'),COMP=document.getElementById('component'),P=document.getElementById('panels'),S=document.getElementById('source'),TABLE=document.getElementById('source-table'),TIP=document.getElementById('tip');
const esc=x=>String(x==null?'':x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=x=>x==null?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:3});
const colors=['#1f4788','#c62828','#2e7d32','#8e44ad','#b45f06','#00838f'];
let zoom=1,pan=0,drag=null,sourceOpen=false;
D.cases.forEach((c,i)=>CASE.add(new Option(c.name,String(i))));CASE.value=String(D.selectedIndex);
function picked(){return D.cases[Number(CASE.value)]||D.cases[0]}
function syncFrames(){const old=FRAME.value;FRAME.options.length=0;picked().frames.forEach((f,i)=>FRAME.add(new Option(f.name,String(i))));FRAME.value=picked().frames.some((f,i)=>String(i)===old)?old:'0'}
function unit(values,kind){const large=Math.max(0,...values.map(v=>Math.abs(v||0)))>=1000;return {factor:large?0.001:1,label:kind==='moment'?(large?'MNm':'kNm'):(large?'MN':'kN')}}
function nice(v){return Number(v).toFixed(2).replace(/\.00$/,'')}
function line(title,xLabel,yLabel,series){const all=series.flatMap(s=>s.points).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(!all.length)return '<p class="empty">No result values for this selection.</p>';
 const W=1000,H=350,L=66,R=22,T=20,B=48;let xmin=Math.min(...all.map(p=>p.x)),xmax=Math.max(...all.map(p=>p.x));if(xmin===xmax){xmin-=.5;xmax+=.5}const mid=(xmin+xmax)/2+pan,half=(xmax-xmin)/(2*zoom),lo=mid-half,hi=mid+half;
 let ymin=Math.min(0,...all.map(p=>p.y)),ymax=Math.max(0,...all.map(p=>p.y));if(ymin===ymax){ymin-=1;ymax+=1}const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;
 const X=v=>L+(v-lo)/(hi-lo)*(W-L-R),Y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-T-B);let h=`<svg class="chart" data-line="1" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}">`;
 for(let i=0;i<=5;i++){const xx=lo+(hi-lo)*i/5,yy=ymin+(ymax-ymin)*i/5;h+=`<path d="M${L} ${nice(Y(yy))}H${W-R} M${nice(X(xx))} ${T}V${H-B}" stroke="#e6e8eb" fill="none"/><text x="${L-8}" y="${nice(Y(yy)+4)}" text-anchor="end">${nice(yy)}</text><text x="${nice(X(xx))}" y="${H-B+18}" text-anchor="middle">${nice(xx)}</text>`}
 h+=`<path d="M${L} ${T}V${H-B}H${W-R} M${L} ${nice(Y(0))}H${W-R}" stroke="#6b7280" fill="none"/><text x="${W/2}" y="${H-6}" text-anchor="middle">${esc(xLabel)}</text><text transform="translate(17 ${H/2}) rotate(-90)" text-anchor="middle">${esc(yLabel)}</text>`;
 series.forEach((s,i)=>{const col=colors[i%colors.length],visible=s.points.filter(p=>p.x>=lo&&p.x<=hi);if(visible.length)h+=`<polyline points="${visible.map(p=>`${nice(X(p.x))},${nice(Y(p.y))}`).join(' ')}" fill="none" stroke="${col}" stroke-width="2"/>`;visible.forEach(p=>h+=`<circle class="hit" cx="${nice(X(p.x))}" cy="${nice(Y(p.y))}" r="6" fill="${col}" data-tip="${esc(s.name+' · '+p.name+'\n'+xLabel+': '+fmt(p.x)+'\n'+yLabel+': '+fmt(p.y))}"/>`)});h+='</svg>';
 return `<section class="panel" data-pr="chart"><h2>${esc(title)}</h2><div class="stage">${h}<aside class="legend">${series.map((s,i)=>`<span class="key"><span class="swatch" style="background:${colors[i%colors.length]}"></span>${esc(s.name)}</span>`).join('')}</aside></div></section>`}
function bars(title,labels,series,kind){const all=series.flatMap(s=>s.values).filter(Number.isFinite);if(!all.length)return '<p class="empty">No result values for this selection.</p>';const u=unit(all,kind),scaled=all.map(v=>v*u.factor),W=1000,H=Math.max(160,70+labels.length*(series.length*24+12)),L=180,R=85,min=Math.min(0,...scaled),max=Math.max(0,...scaled),span=max-min||1;
 const X=v=>L+(v-min)/span*(W-L-R);let h=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}"><path d="M${nice(X(0))} 24V${H-22}" stroke="#6b7280"/>`;
 labels.forEach((name,i)=>{const y=36+i*(series.length*24+12);h+=`<text x="${L-8}" y="${y+12}" text-anchor="end">${esc(name)}</text>`;series.forEach((s,j)=>{const v=s.values[i];if(!Number.isFinite(v))return;const q=v*u.factor,yy=y+j*24,col=colors[j%colors.length];h+=`<rect x="${nice(Math.min(X(0),X(q)))}" y="${yy}" width="${nice(Math.max(1,Math.abs(X(q)-X(0))))}" height="16" fill="${col}" class="hit" data-tip="${esc(name+' · '+s.name+'\n'+fmt(q)+' '+u.label+' ('+fmt(v)+' '+(kind==='moment'?'kNm':'kN')+')')}"/><text x="${nice(X(q)+(q<0?-5:5))}" y="${yy+12}" text-anchor="${q<0?'end':'start'}">${fmt(q)}</text>`})});h+='</svg>';
 return `<section class="panel" data-pr="chart"><h2>${esc(title)} [${u.label}]</h2><div class="stage">${h}<aside class="legend">${series.map((s,i)=>`<span class="key"><span class="swatch" style="background:${colors[i%colors.length]}"></span>${esc(s.name)}</span>`).join('')}</aside></div></section>`}
function table(headers,rows){const cell=x=>esc(x==null?'—':typeof x==='number'?fmt(x):x);return `<table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${cell(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function render(){const c=picked(),topic=TOPIC.value,frame=c.frames[Number(FRAME.value)],comp=COMP.value;document.getElementById('frame-wrap').hidden=topic!=='frame';document.getElementById('component-wrap').hidden=topic!=='frame';const canZoom=topic==='deflection'||topic==='frame';['zoom-in','zoom-out','reset'].forEach(id=>document.getElementById(id).disabled=!canZoom);
 let chart='',headers=[],rows=[];
 if(topic==='deflection'){const groups={};c.joints.forEach(j=>{const key=nice(j.z);(groups[key]||(groups[key]=[])).push(j)});chart=line('Vertical deflection by level',D.hasGeometry?'X [m]':'Joint index','Uz [mm]',Object.keys(groups).sort((a,b)=>+a- +b).map(z=>({name:'Z = '+z+' m',points:groups[z].sort((a,b)=>a.x-b.x).map(j=>({x:j.x,y:j.uz,name:j.name}))})));headers=['Joint','X [m]','Z [m]','Ux [mm]','Uz [mm]','Rotation [rad]'];rows=c.joints.map(j=>[j.name,j.x,j.z,j.ux,j.uz,j.rotation])}
 else if(topic==='frame'){if(frame){const key={n:'n',v:'v',m:'m'}[comp],title={n:'Axial force',v:'Shear force',m:'Bending moment'}[comp],values=frame.stations.map(s=>s[key]),u=unit(values,comp==='m'?'moment':'force');chart=line(title+' · '+frame.name,'Station [% from I-end]',{n:'N',v:'V',m:'M'}[comp]+' ['+u.label+']',[{name:frame.name,points:frame.stations.map(s=>({x:s.x,y:s[key]*u.factor,name:frame.name}))}]);headers=['Member','Station [%]','N [kN]','V [kN]','M [kNm]'];rows=frame.stations.map(s=>[frame.name,s.x,s.n,s.v,s.m])}else chart='<p class="empty">No frame forces in this case.</p>'}
 else if(topic==='reaction'){chart=bars('Support reactions',c.reactions.map(x=>x.name),[{name:'Rx',values:c.reactions.map(x=>x.rx)},{name:'Rz',values:c.reactions.map(x=>x.rz)}],'force');headers=['Joint','Rx [kN]','Rz [kN]'];rows=c.reactions.map(x=>[x.name,x.rx,x.rz])}
 else{chart=bars('Cable forces / target fit',c.cables.map(x=>x.name),[{name:'Target',values:c.cables.map(x=>x.target)},{name:'Pretension stage',values:c.cables.map(x=>x.stage)},{name:'Result',values:c.cables.map(x=>x.result)}],'force');if(c.fitFailure)chart+=`<p class="warning">Target fit: ${esc(c.fitFailure)}</p>`;headers=['Cable','Target [kN]','Stage [kN]','Result [kN]','State','Sag [mm]','Stiffness [%]'];rows=c.cables.map(x=>[x.name,x.target,x.stage,x.result,x.active?'Taut':'Slack',x.sagMm,x.stiffnessPercent])}
 P.innerHTML=chart;TABLE.innerHTML=table(headers,rows);const chosen=[...TOPIC.options].find(o=>o.value===topic),view=c.name+' · '+(chosen?chosen.text:topic);document.getElementById('scope').textContent=view;document.getElementById('print-view').textContent=view;S.hidden=!sourceOpen;document.getElementById('source-toggle').setAttribute('aria-expanded',String(sourceOpen))}
CASE.onchange=()=>{zoom=1;pan=0;syncFrames();render()};TOPIC.onchange=()=>{zoom=1;pan=0;render()};FRAME.onchange=COMP.onchange=()=>{zoom=1;pan=0;render()};
document.getElementById('zoom-in').onclick=()=>{zoom=Math.min(32,zoom*1.5);render()};document.getElementById('zoom-out').onclick=()=>{zoom=Math.max(1,zoom/1.5);if(zoom===1)pan=0;render()};document.getElementById('reset').onclick=()=>{zoom=1;pan=0;render()};
document.getElementById('source-toggle').onclick=()=>{sourceOpen=!sourceOpen;render()};P.ondblclick=()=>{zoom=1;pan=0;render()};P.onwheel=e=>{if(!e.target.closest('svg[data-line]'))return;e.preventDefault();zoom=Math.max(1,Math.min(32,zoom*(e.deltaY<0?1.2:1/1.2)));if(zoom===1)pan=0;render()};
P.onpointerdown=e=>{if(e.target.closest('svg[data-line]'))drag={x:e.clientX,pan}};window.addEventListener('pointerup',()=>drag=null);P.onpointermove=e=>{if(drag){const c=picked(),f=c.frames[Number(FRAME.value)],pts=TOPIC.value==='frame'?(f?f.stations.map(x=>x.x):[]):c.joints.map(x=>x.x),span=pts.length?Math.max(...pts)-Math.min(...pts):0;pan=drag.pan-(e.clientX-drag.x)*span/(Math.max(1,P.clientWidth||900)*zoom);render()}};
P.onmousemove=e=>{const hit=e.target.closest('[data-tip]');if(!hit){TIP.hidden=true;return}TIP.textContent=hit.dataset.tip;TIP.hidden=false;TIP.style.left=Math.min(innerWidth-325,e.clientX+12)+'px';TIP.style.top=Math.min(innerHeight-130,e.clientY+12)+'px'};P.onmouseleave=()=>TIP.hidden=true;
window.femReport={render,selectCase:i=>{CASE.value=String(i);CASE.selectedIndex=Number(i);CASE.onchange()},selectTopic:t=>{TOPIC.value=t;TOPIC.selectedIndex=[...TOPIC.options].findIndex(o=>o.value===t);TOPIC.onchange()},state:()=>({caseName:picked().name,topic:TOPIC.value,zoom,pan})};syncFrames();render();
})();
""";
}
